INSERT INTO "Exercises" ("ExerciseId", "Name", "Sets", "Reps", "DurationMinutes", "Description", "DescriptionAr", "Difficulty", "Category", "VideoUrl", "CreatedAt", "UpdatedAt", "IsDeleted")
VALUES
  (gen_random_uuid(), '40 Degrees Shoulder External Rotation', 3, 10, 10, 'Stand or sit with your elbow bent at 90 degrees and tucked to your side. Hold a light resistance band with your affected hand. Slowly rotate your forearm outward about 40 degrees, keeping the elbow fixed. Pause briefly at the end range. Return slowly to the starting position and repeat.', 'قف أو اجلس مع ثني الكوع بزاوية 90 درجة وتثبيته بجانب الجسم. أمسك شريط مقاومة خفيف باليد المصابة. أدر الساعد للخارج بحوالي 40 درجة مع تثبيت الكوع. توقف لحظة عند نهاية الحركة. عد ببطء إلى وضع البداية وكرر التمرين.', 1, 0, 'https://youtu.be/fQcoDTBgjdg', now(), now(), false),
  (gen_random_uuid(), 'Bent-Over Elbow Flexion', 3, 10, 10, 'Stand with feet shoulder-width apart and lean forward from the hips. Let the arm hang straight down while holding a light dumbbell. Slowly bend the elbow, bringing the weight toward the shoulder. Keep the upper arm still throughout the movement. Lower the weight with control and repeat.', 'قف والقدمان بعرض الكتفين وانحنِ للأمام من منطقة الوركين. اترك الذراع متدلية للأسفل ممسكاً بدمبل خفيف. اثنِ الكوع ببطء لرفع الوزن باتجاه الكتف. حافظ على ثبات الذراع العلوية طوال الحركة. أنزل الوزن بتحكم وكرر التمرين.', 0, 1, 'https://youtu.be/Z3eyQwAQrqA', now(), now(), false),
  (gen_random_uuid(), 'Active-Assisted Elbow Flexion', 3, 10, 10, 'Sit upright with the affected arm resting on a table or your thigh. Use your healthy hand to gently support the affected wrist. Slowly bend the affected elbow with help from the other hand. Bring the hand toward the shoulder as far as comfortable. Straighten the arm slowly and repeat.', 'اجلس بشكل مستقيم مع وضع الذراع المصابة على طاولة أو الفخذ. استخدم اليد السليمة لدعم رسغ الذراع المصابة بلطف. اثنِ كوع الذراع المصابة ببطء بمساعدة اليد الأخرى. قرّب اليد من الكتف بقدر ما تسمح الراحة. افرد الذراع ببطء وكرر التمرين.', 0, 1, 'https://youtu.be/CdiKBB2h2sQ', now(), now(), false),
  (gen_random_uuid(), 'Active-Assisted Shoulder Abduction', 3, 10, 10, 'Stand or sit tall with arms relaxed at your sides. Interlock the fingers of both hands together in front of you. Let the healthy arm guide the affected arm out to the side. Raise both arms sideways as high as comfortable. Lower slowly back to the starting position and repeat.', 'قف أو اجلس بشكل مستقيم مع إرخاء الذراعين بجانب الجسم. شبّك أصابع اليدين معاً أمامك. اجعل الذراع السليمة توجه الذراع المصابة للخارج. ارفع الذراعين للجانب لأعلى ارتفاع مريح. أنزلهما ببطء إلى وضع البداية وكرر.', 0, 0, 'https://youtu.be/wmmUgxdNf24', now(), now(), false),
  (gen_random_uuid(), 'Active-Assisted Shoulder Flexion with Stick', 3, 10, 10, 'Stand or sit tall while holding a stick with both hands in front. Use the healthy arm to push the stick and affected arm upward. Raise both arms overhead as high as comfortable. Hold briefly at the top position. Lower the stick slowly and repeat.', 'قف أو اجلس بشكل مستقيم ممسكاً بعصا بكلتا اليدين أمامك. استخدم الذراع السليمة لدفع العصا والذراع المصابة للأعلى. ارفع الذراعين فوق الرأس لأقصى ارتفاع مريح. توقف لحظة عند الأعلى. أنزل العصا ببطء وكرر التمرين.', 0, 0, 'https://youtu.be/L2DQfw_Oxd8', now(), now(), false),
  (gen_random_uuid(), 'Alternate Arm & Leg Raises', 3, 10, 10, 'Start on hands and knees in a tabletop position. Keep your back flat and core engaged. Extend the right arm forward and left leg backward at the same time. Hold for 2–3 seconds keeping the body stable. Return to start and switch sides.', 'ابدأ على اليدين والركبتين بوضع الطاولة. حافظ على ظهر مستقيم وشد عضلات البطن. مدّ الذراع اليمنى للأمام والساق اليسرى للخلف في نفس الوقت. ثبّت الوضع لمدة 2–3 ثوانٍ مع استقرار الجسم. عد لوضع البداية وبدّل الجانبين.', 1, 4, 'https://youtu.be/RyMDYRonsck', now(), now(), false),
  (gen_random_uuid(), 'Angel Swings', 3, 10, 10, 'Stand tall with arms straight down at your sides, palms forward. Slowly raise both arms out to the sides and overhead like making a snow angel. Keep the arms straight throughout the movement. Squeeze the shoulder blades together at the top. Lower the arms slowly and repeat.', 'قف بشكل مستقيم مع إنزال الذراعين وراحة اليدين للأمام. ارفع الذراعين ببطء إلى الجانبين ثم فوق الرأس كملاك الثلج. حافظ على استقامة الذراعين طوال الحركة. اضغط لوحي الكتف معاً في الأعلى. أنزل الذراعين ببطء وكرر.', 0, 0, 'https://youtu.be/dnD8RKq2mu8', now(), now(), false),
  (gen_random_uuid(), 'Arm Cross Stretch with Rotation', 3, 10, 10, 'Stand tall and bring one arm across your chest. Use the opposite hand to gently pull the arm closer. Slowly rotate your torso in the same direction as the stretch. Hold for 15–20 seconds while breathing normally. Release and repeat on the other side.', 'قف بشكل مستقيم وضع إحدى الذراعين عبر الصدر. استخدم اليد الأخرى لسحب الذراع بلطف نحو الجسم. أدر الجذع ببطء في نفس اتجاه الشد. ثبّت لمدة 15–20 ثانية مع التنفس الطبيعي. استرخِ وكرر على الجانب الآخر.', 0, 0, 'https://youtu.be/ruRW1RFOQzk', now(), now(), false),
  (gen_random_uuid(), 'Ball Squeeze Between Knees', 3, 10, 10, 'Lie on your back with knees bent and feet flat on the floor. Place a soft ball between your knees. Squeeze the ball firmly using your inner thigh muscles. Hold the squeeze for 5 seconds. Relax and repeat.', 'استلقِ على ظهرك مع ثني الركبتين ووضع القدمين على الأرض. ضع كرة طرية بين الركبتين. اضغط على الكرة بقوة باستخدام عضلات الفخذ الداخلية. ثبّت الضغطة لمدة 5 ثوانٍ. استرخِ وكرر التمرين.', 0, 5, 'https://youtu.be/IrkHCXRQ8dQ', now(), now(), false),
  (gen_random_uuid(), 'Bent-Over Lateral Raise', 3, 10, 10, 'Stand with feet shoulder-width apart and lean forward from the hips. Hold a light dumbbell in each hand with arms hanging down. Raise both arms out to the sides until parallel to the floor. Squeeze the shoulder blades together at the top. Lower the weights slowly and repeat.', 'قف والقدمان بعرض الكتفين وانحنِ للأمام من الوركين. أمسك دمبل خفيف بكل يد مع تدلي الذراعين للأسفل. ارفع الذراعين إلى الجانبين حتى تصبحا موازيتين للأرض. اضغط لوحي الكتف معاً في الأعلى. أنزل الأوزان ببطء وكرر.', 1, 0, 'https://youtu.be/-_zA8BjO-LA', now(), now(), false),
  (gen_random_uuid(), 'Bent-Over Resisted Rows', 3, 10, 10, 'Stand on a resistance band with feet shoulder-width apart. Bend forward from the hips with knees slightly bent. Grip the band handles with arms hanging down. Pull the handles toward your ribs, squeezing shoulder blades. Lower slowly with control and repeat.', 'قف على شريط المقاومة والقدمان بعرض الكتفين. انحنِ للأمام من الوركين مع ثني الركبتين قليلاً. أمسك مقابض الشريط مع تدلي الذراعين للأسفل. اسحب المقابض نحو الأضلاع مع ضغط لوحي الكتف. أنزل ببطء بتحكم وكرر التمرين.', 1, 0, 'https://youtu.be/KAUT-khjGqQ', now(), now(), false),
  (gen_random_uuid(), 'Bent-Over Rows', 3, 10, 10, 'Stand with feet shoulder-width apart, knees slightly bent. Lean forward from the hips holding a dumbbell in each hand. Keep your back flat and core engaged. Pull the weights up toward your ribs, squeezing shoulder blades. Lower the weights slowly and repeat.', 'قف والقدمان بعرض الكتفين والركبتان مثنيتان قليلاً. انحنِ للأمام من الوركين ممسكاً بدمبل بكل يد. حافظ على ظهر مستقيم وشد عضلات البطن. اسحب الأوزان نحو الأضلاع مع ضغط لوحي الكتف. أنزل الأوزان ببطء وكرر.', 1, 0, 'https://youtu.be/6SC1WhYiDfk', now(), now(), false),
  (gen_random_uuid(), 'Both Arms Overhead Stretch', 3, 10, 10, 'Stand or sit tall with arms relaxed at your sides. Interlock your fingers together and turn palms upward. Slowly raise both arms straight overhead. Reach as high as comfortable and hold 15–20 seconds. Lower the arms slowly and repeat.', 'قف أو اجلس بشكل مستقيم مع إرخاء الذراعين. شبّك الأصابع واقلب راحة اليدين للأعلى. ارفع الذراعين ببطء فوق الرأس مستقيمتين. امتد لأقصى ارتفاع مريح لمدة 15–20 ثانية. أنزل الذراعين ببطء وكرر.', 0, 0, 'https://youtu.be/ohuAChPBLMY', now(), now(), false),
  (gen_random_uuid(), 'Both Knees to Chest', 3, 10, 10, 'Lie on your back with legs straight. Bend both knees and bring them toward your chest. Wrap your arms around your shins. Gently pull the knees closer, feeling a stretch in the lower back. Hold 15–20 seconds then return to start.', 'استلقِ على ظهرك والساقان مستقيمتان. اثنِ الركبتين وقرّبهما من الصدر. لفّ ذراعيك حول الساقين. اسحب الركبتين بلطف مع الشعور بشد في أسفل الظهر. ثبّت لمدة 15–20 ثانية ثم عد للبداية.', 0, 3, 'https://youtu.be/PbkAv_nhfFY', now(), now(), false),
  (gen_random_uuid(), 'Bridging (2)', 3, 10, 10, 'Lie on your back with knees bent and feet flat on the floor. Place your arms flat at your sides for support. Tighten your glutes and lift your hips toward the ceiling. Form a straight line from shoulders to knees. Hold briefly then lower slowly and repeat.', 'استلقِ على ظهرك مع ثني الركبتين ووضع القدمين على الأرض. ضع الذراعين على الجانبين للدعم. اشدّ عضلات الأرداف وارفع الوركين للأعلى. كوّن خطاً مستقيماً من الكتفين إلى الركبتين. ثبّت لحظة ثم أنزل ببطء وكرر.', 0, 4, NULL, now(), now(), false),
  (gen_random_uuid(), 'Bridging', 3, 10, 10, 'Lie flat on your back with knees bent and feet hip-width apart. Rest arms at your sides with palms down. Push through your heels and lift your hips upward. Squeeze your glutes at the top position. Lower your hips slowly and repeat.', 'استلقِ على ظهرك مع ثني الركبتين والقدمين بعرض الوركين. ضع الذراعين على الجانبين وراحة اليدين للأسفل. ادفع من خلال الكعبين وارفع الوركين لأعلى. اضغط عضلات الأرداف في الأعلى. أنزل الوركين ببطء وكرر.', 0, 4, 'https://youtu.be/FL7hOFswfK8', now(), now(), false),
  (gen_random_uuid(), 'Butterfly Stretch', 3, 10, 10, 'Sit on the floor with your back straight. Bring the soles of your feet together in front of you. Hold your feet with your hands and let knees fall outward. Gently press your knees toward the floor. Hold 20–30 seconds, breathing steadily.', 'اجلس على الأرض مع استقامة الظهر. اجمع باطن القدمين معاً أمامك. أمسك القدمين باليدين ودع الركبتين تسقطان للجانبين. اضغط الركبتين بلطف نحو الأرض. ثبّت لمدة 20–30 ثانية مع التنفس الهادئ.', 0, 5, 'https://youtu.be/-UOYvSZTjKA', now(), now(), false),
  (gen_random_uuid(), 'Cat-Cow Stretch', 3, 10, 10, 'Start on hands and knees in tabletop position. Inhale as you drop your belly and lift your head (Cow). Exhale as you round your spine and tuck your chin (Cat). Move slowly between the two positions. Repeat for 8–10 flowing cycles.', 'ابدأ على اليدين والركبتين بوضع الطاولة. استنشق وأنزل البطن وارفع الرأس (البقرة). ازفر وقوّس الظهر واضمّ الذقن (القطة). تحرك ببطء بين الوضعين. كرر لمدة 8–10 دورات متتابعة.', 0, 3, 'https://youtu.be/6cxx8gDv82c', now(), now(), false),
  (gen_random_uuid(), 'Chest Expansion', 3, 10, 10, 'Stand tall with feet hip-width apart. Clasp your hands behind your lower back. Lift the chest and squeeze the shoulder blades together. Gently pull the arms down and back. Hold 15–20 seconds while breathing deeply.', 'قف بشكل مستقيم والقدمان بعرض الوركين. شبّك اليدين خلف أسفل الظهر. ارفع الصدر واضغط لوحي الكتف معاً. اسحب الذراعين بلطف للأسفل والخلف. ثبّت لمدة 15–20 ثانية مع التنفس العميق.', 0, 0, 'https://youtu.be/mNibufBnOgA', now(), now(), false),
  (gen_random_uuid(), 'Child Stretch', 3, 10, 10, 'Kneel on the floor and sit back on your heels. Reach both arms forward on the ground. Lower your forehead toward the floor. Feel a stretch through the back and shoulders. Hold 30 seconds while breathing steadily.', 'اركع على الأرض واجلس على كعبيك. مدّ الذراعين للأمام على الأرض. أنزل جبهتك نحو الأرض. اشعر بالشد في الظهر والكتفين. ثبّت لمدة 30 ثانية مع التنفس الهادئ.', 0, 3, 'https://youtu.be/d-Zp5fFbo_A', now(), now(), false),
  (gen_random_uuid(), 'Cobra Stretch', 3, 10, 10, 'Lie face down with hands under your shoulders. Keep your hips and legs pressed to the floor. Push up through your arms, lifting the chest. Look slightly upward without straining the neck. Hold 15–20 seconds then lower down.', 'استلقِ على البطن ويداك تحت الكتفين. حافظ على تثبيت الوركين والساقين على الأرض. ادفع بالذراعين وارفع الصدر. انظر قليلاً للأعلى دون إجهاد الرقبة. ثبّت لمدة 15–20 ثانية ثم أنزل.', 0, 3, 'https://youtu.be/XZ3YQlS-BOw', now(), now(), false),
  (gen_random_uuid(), 'Cross Arm in Quadruped Position', 3, 10, 10, 'Start on hands and knees with a flat back. Slide one arm under your body across to the opposite side. Rest your shoulder and head on the floor. Feel the stretch through the upper back and shoulder. Hold 20–30 seconds then switch sides.', 'ابدأ على اليدين والركبتين مع استقامة الظهر. مرّر إحدى الذراعين تحت الجسم للجانب الآخر. ضع الكتف والرأس على الأرض. اشعر بالشد في أعلى الظهر والكتف. ثبّت لمدة 20–30 ثانية ثم بدّل.', 0, 0, 'https://youtu.be/YnbyTJnsU8Q', now(), now(), false),
  (gen_random_uuid(), 'Cross-Leg Piriformis Stretch', 3, 10, 10, 'Lie on your back with knees bent. Cross the right ankle over the left thigh. Grasp behind the left thigh with both hands. Pull the left leg toward your chest. Hold 20–30 seconds then switch sides.', 'استلقِ على ظهرك مع ثني الركبتين. ضع كاحل القدم اليمنى على الفخذ الأيسر. أمسك خلف الفخذ الأيسر بكلتا اليدين. اسحب الساق اليسرى نحو الصدر. ثبّت لمدة 20–30 ثانية ثم بدّل.', 0, 5, 'https://youtu.be/GOg_TyZNkG4', now(), now(), false),
  (gen_random_uuid(), 'Crossed Leg Push', 3, 10, 10, 'Sit on the floor with one leg crossed over the other. Place the opposite elbow on the outside of the raised knee. Gently push the knee across the body while rotating the torso. Look over the shoulder of the twisted side. Hold 20–30 seconds then switch sides.', 'اجلس على الأرض مع تقاطع ساق فوق الأخرى. ضع الكوع المعاكس على خارج الركبة المرفوعة. ادفع الركبة بلطف عبر الجسم مع تدوير الجذع. انظر فوق الكتف في اتجاه اللف. ثبّت 20–30 ثانية ثم بدّل الجانبين.', 0, 5, 'https://youtu.be/aWWMlNcA_pM', now(), now(), false),
  (gen_random_uuid(), 'Crossed Legs Toe Touch', 3, 10, 10, 'Stand upright and cross one foot in front of the other. Keep the legs straight but not locked. Slowly bend forward from the hips. Reach your fingers toward your toes. Hold 15–20 seconds, then switch leg crossings.', 'قف بشكل مستقيم مع تقاطع قدم أمام الأخرى. حافظ على استقامة الساقين دون قفلهما. انحنِ ببطء للأمام من الوركين. مدّ الأصابع نحو أصابع القدمين. ثبّت 15–20 ثانية ثم بدّل التقاطع.', 0, 3, 'https://youtu.be/O8qjx9Ul1zI', now(), now(), false),
  (gen_random_uuid(), 'Crossed Legs Trunk Flexion', 3, 10, 10, 'Sit on the floor with legs crossed. Keep your back tall and shoulders relaxed. Slowly bend your trunk forward from the hips. Reach your arms out along the floor. Hold 20–30 seconds then sit back up.', 'اجلس على الأرض مع تقاطع الساقين. حافظ على استقامة الظهر واسترخاء الكتفين. انحنِ بالجذع ببطء للأمام من الوركين. مدّ الذراعين على الأرض. ثبّت 20–30 ثانية ثم عد للجلوس.', 0, 3, 'https://youtu.be/zeI2te9DXOE', now(), now(), false),
  (gen_random_uuid(), 'Crunches', 3, 10, 10, 'Lie on your back with knees bent and feet flat on the floor. Place hands lightly behind your head. Engage your core and lift your shoulders off the floor. Keep the lower back pressed to the ground. Lower slowly and repeat.', 'استلقِ على ظهرك مع ثني الركبتين ووضع القدمين على الأرض. ضع اليدين خلف الرأس بشكل خفيف. شدّ عضلات البطن وارفع الكتفين عن الأرض. حافظ على تثبيت أسفل الظهر على الأرض. أنزل ببطء وكرر التمرين.', 1, 4, 'https://youtu.be/ATEDxj_pn7o', now(), now(), false),
  (gen_random_uuid(), 'Deadlifts', 3, 10, 10, 'Stand with feet hip-width apart, a barbell or dumbbells in front. Bend at the hips and knees to grip the weight. Keep the back flat and chest lifted. Drive through the heels to stand up straight. Lower the weight with control and repeat.', 'قف والقدمان بعرض الوركين والأوزان أمامك. انحنِ من الوركين والركبتين لإمساك الوزن. حافظ على استقامة الظهر ورفع الصدر. ادفع من خلال الكعبين للوقوف باستقامة. أنزل الوزن بتحكم وكرر.', 2, 5, 'https://youtu.be/TItnVp9sc1s', now(), now(), false),
  (gen_random_uuid(), 'Dropped Arms Scapular Squeeze', 3, 10, 10, 'Stand or sit tall with arms hanging at your sides. Keep your chest lifted and shoulders relaxed. Squeeze your shoulder blades together and downward. Hold the squeeze for 5 seconds. Release slowly and repeat.', 'قف أو اجلس بشكل مستقيم والذراعان متدليتان. حافظ على رفع الصدر واسترخاء الكتفين. اضغط لوحي الكتف معاً وللأسفل. ثبّت الضغطة لمدة 5 ثوانٍ. استرخِ ببطء وكرر التمرين.', 0, 0, 'https://youtu.be/U-kh1kUk3OA', now(), now(), false),
  (gen_random_uuid(), 'Elbow 90° Flexion with Ball Squeeze', 3, 10, 10, 'Sit or stand with the elbow bent at 90 degrees. Tuck the elbow close to your side. Hold a soft ball in your hand. Squeeze the ball firmly and hold for 5 seconds. Release slowly and repeat.', 'اجلس أو قف مع ثني الكوع بزاوية 90 درجة. ثبّت الكوع بجانب الجسم. أمسك كرة طرية باليد. اضغط الكرة بقوة وثبّت لمدة 5 ثوانٍ. استرخِ ببطء وكرر.', 0, 1, 'https://youtu.be/yvH2icv5FLk', now(), now(), false),
  (gen_random_uuid(), 'Elbow Flexion', 3, 10, 10, 'Stand or sit tall with the arm at your side. Hold a light dumbbell in your hand, palm facing up. Slowly bend the elbow, bringing the weight toward the shoulder. Keep the upper arm still throughout. Lower with control and repeat.', 'قف أو اجلس بشكل مستقيم والذراع بجانب الجسم. أمسك دمبل خفيف باليد وراحة اليد للأعلى. اثنِ الكوع ببطء لرفع الوزن نحو الكتف. حافظ على ثبات الذراع العلوية. أنزل بتحكم وكرر التمرين.', 0, 1, 'https://youtu.be/9dItqSoCkzM', now(), now(), false),
  (gen_random_uuid(), 'Elbow Flexion to 90° with Wrist Flexion/Extension', 3, 10, 10, 'Sit or stand with elbow bent at 90 degrees at your side. Keep the upper arm still throughout. Slowly bend the wrist upward, then downward. Move through the full comfortable range. Return to neutral and repeat.', 'اجلس أو قف مع ثني الكوع 90 درجة بجانب الجسم. حافظ على ثبات الذراع العلوية. اثنِ الرسغ ببطء للأعلى ثم للأسفل. تحرك عبر النطاق الكامل المريح. عد إلى الوضع المحايد وكرر.', 0, 2, 'https://youtu.be/-8t8GV1kb_o', now(), now(), false),
  (gen_random_uuid(), 'Elbow Flexion with Fingers Flexion/Extension', 3, 10, 10, 'Sit or stand with the elbow bent at 90 degrees. Slowly close your fingers into a fist. Then open the fingers fully and stretch them out. Coordinate movement smoothly with the elbow bent. Repeat for the prescribed reps.', 'اجلس أو قف مع ثني الكوع 90 درجة. أغلق أصابعك ببطء لتكوين قبضة. ثم افتحها بالكامل ومدّها للخارج. نسّق الحركة بسلاسة مع ثني الكوع. كرر التمرين للعدد المطلوب.', 0, 2, 'https://youtu.be/IMq_MnmUFQ8', now(), now(), false),
  (gen_random_uuid(), 'Elbow Flexion with Punch', 3, 10, 10, 'Sit or stand with elbow bent at 90 degrees, fist closed. Keep the upper arm at your side. Punch forward by extending the elbow fully. Return the fist to the bent starting position. Repeat with a smooth, controlled tempo.', 'اجلس أو قف مع ثني الكوع 90 درجة وإغلاق القبضة. حافظ على الذراع العلوية بجانب الجسم. اضرب للأمام بمدّ الكوع بالكامل. أعد القبضة إلى وضع البداية المثني. كرر بإيقاع سلس ومتحكم به.', 1, 1, 'https://youtu.be/nWowxQbexYg', now(), now(), false),
  (gen_random_uuid(), 'Elbow Flexion with Wrist Extension', 3, 10, 10, 'Sit or stand with the arm at your side. Bend the elbow while extending the wrist backward. Keep the upper arm still throughout. Bring the hand toward the shoulder with the wrist extended. Return slowly to start and repeat.', 'اجلس أو قف والذراع بجانب الجسم. اثنِ الكوع مع مدّ الرسغ للخلف. حافظ على ثبات الذراع العلوية. قرّب اليد من الكتف والرسغ ممدود. عد ببطء إلى البداية وكرر.', 0, 2, 'https://youtu.be/bD1hrw2BQcM', now(), now(), false),
  (gen_random_uuid(), 'External Rotation Diagonal Up', 3, 10, 10, 'Stand holding a resistance band anchored at hip level. Start with the hand at the opposite hip. Rotate the arm outward and upward on a diagonal. End with the arm above shoulder height, thumb up. Return slowly along the same diagonal and repeat.', 'قف ممسكاً بشريط مقاومة مثبت عند مستوى الورك. ابدأ واليد عند الورك المعاكس. أدر الذراع للخارج والأعلى بشكل قطري. انهِ مع الذراع فوق مستوى الكتف والإبهام للأعلى. عد ببطء بنفس الاتجاه القطري وكرر.', 1, 0, 'https://youtu.be/4ekTx1Mwcfo', now(), now(), false),
  (gen_random_uuid(), 'Finger Extension on Table', 3, 10, 10, 'Rest your hand flat on a table, palm down. Keep the wrist relaxed on the surface. Lift each finger off the table one at a time. Hold each lift briefly at the top. Lower slowly and continue with all fingers.', 'ضع يدك مسطحة على طاولة وراحة اليد للأسفل. حافظ على استرخاء الرسغ على السطح. ارفع كل إصبع عن الطاولة واحداً تلو الآخر. ثبّت كل رفعة لحظة في الأعلى. أنزل ببطء وتابع مع باقي الأصابع.', 0, 2, 'https://youtu.be/REf0MGKd5h4', now(), now(), false),
  (gen_random_uuid(), 'Finger Extension Using Band', 3, 10, 10, 'Place a rubber band around all your fingers and thumb. Keep the hand in a relaxed position. Slowly spread the fingers apart against the band''s resistance. Hold the open position for 3–5 seconds. Relax and repeat.', 'ضع شريطاً مطاطياً حول جميع الأصابع والإبهام. حافظ على استرخاء اليد. افرد الأصابع للخارج ببطء ضد مقاومة الشريط. ثبّت وضع الفتح لمدة 3–5 ثوانٍ. استرخِ وكرر التمرين.', 0, 2, 'https://youtu.be/gbQS-rHoJH0', now(), now(), false),
  (gen_random_uuid(), 'Finger Pinches', 3, 10, 10, 'Hold a small soft object between your thumb and one finger. Squeeze the object firmly using pinch pressure. Hold the pinch for 3–5 seconds. Release and switch to the next finger. Continue through each finger of the hand.', 'أمسك جسماً صغيراً طرياً بين الإبهام وأحد الأصابع. اضغط الجسم بقوة باستخدام حركة القرص. ثبّت القرصة لمدة 3–5 ثوانٍ. استرخِ وانتقل إلى الإصبع التالي. تابع مع جميع أصابع اليد.', 0, 2, 'https://youtu.be/aji5JtC6PwM', now(), now(), false),
  (gen_random_uuid(), 'Finger Stretch', 3, 10, 10, 'Rest the hand flat with fingers together. Use the other hand to gently stretch fingers apart. Then stretch fingers backward one at a time. Hold each stretch for 10–15 seconds. Release and repeat as needed.', 'ضع اليد مسطحة والأصابع مضمومة. استخدم اليد الأخرى لتباعد الأصابع بلطف. ثم اسحب كل إصبع للخلف واحداً تلو الآخر. ثبّت كل شدّة لمدة 10–15 ثانية. استرخِ وكرر عند الحاجة.', 0, 2, 'https://youtu.be/skt0EFYRIhE', now(), now(), false),
  (gen_random_uuid(), 'Fingers Abduction', 3, 10, 10, 'Place the hand flat on a table, palm down. Keep all fingers straight and together. Slowly spread the fingers apart as wide as possible. Hold the spread position for 3–5 seconds. Bring fingers back together and repeat.', 'ضع اليد مسطحة على طاولة وراحة اليد للأسفل. حافظ على استقامة الأصابع مضمومة. فرّق الأصابع ببطء لأقصى مدى ممكن. ثبّت وضع التباعد لمدة 3–5 ثوانٍ. أعد الأصابع للتقارب وكرر.', 0, 2, 'https://youtu.be/uwr2BLJRiJY', now(), now(), false),
  (gen_random_uuid(), 'Fingers Extension', 3, 10, 10, 'Rest the forearm on a table with the palm down. Start with all fingers bent slightly. Slowly straighten all fingers, lifting them upward. Hold at the extended position briefly. Return to the starting bend and repeat.', 'ضع الساعد على طاولة وراحة اليد للأسفل. ابدأ مع ثني جميع الأصابع قليلاً. افرد كل الأصابع ببطء برفعها للأعلى. ثبّت في وضع الفرد لحظة. عد إلى الوضع المثني وكرر.', 0, 2, 'https://youtu.be/i45diOEExgw', now(), now(), false),
  (gen_random_uuid(), 'Fist Overpressure', 3, 10, 10, 'Make a tight fist with the affected hand. Use the other hand to gently press over the fist. Increase the squeeze slightly at end range. Hold the pressure for 3–5 seconds. Release and repeat.', 'كوّن قبضة قوية باليد المصابة. استخدم اليد الأخرى للضغط بلطف فوق القبضة. زد الضغط قليلاً في نهاية الحركة. ثبّت الضغط لمدة 3–5 ثوانٍ. استرخِ وكرر.', 0, 2, 'https://youtu.be/myoBEdi5OYc', now(), now(), false),
  (gen_random_uuid(), 'Foam Roller Wall Slides', 3, 10, 10, 'Stand with a foam roller against a wall behind your back. Place your forearms on the wall in a goalpost position. Slowly slide the arms upward along the wall. Keep contact with the roller throughout. Lower the arms slowly and repeat.', 'قف مع وضع اسطوانة الفوم بين الظهر والحائط. ضع ساعديك على الحائط بوضع مرمى. اسحب الذراعين ببطء للأعلى على الحائط. حافظ على تلامس الاسطوانة طوال الحركة. أنزل الذراعين ببطء وكرر.', 0, 0, 'https://youtu.be/ZLOySBmF6HU', now(), now(), false),
  (gen_random_uuid(), 'Forearm Supination and Pronation', 3, 10, 10, 'Sit with the elbow bent at 90 degrees at your side. Hold a light object in your hand. Rotate the palm upward (supination), then downward (pronation). Keep the elbow tucked and still. Move slowly through the full range.', 'اجلس مع ثني الكوع 90 درجة بجانب الجسم. أمسك جسماً خفيفاً باليد. أدر راحة اليد للأعلى (استلقاء) ثم للأسفل (كبّ). حافظ على تثبيت الكوع بجانب الجسم. تحرك ببطء عبر النطاق الكامل.', 0, 1, 'https://youtu.be/zVfbLBz0t1w', now(), now(), false),
  (gen_random_uuid(), 'Isometric Lateral Raises', 3, 10, 10, 'Stand next to a wall with the arm at your side. Keep the elbow straight and press the back of the hand against the wall. Push outward as if lifting the arm sideways. Hold the push for 5–10 seconds without moving. Relax and repeat.', 'قف بجانب حائط والذراع بجانب الجسم. حافظ على استقامة الكوع واضغط ظهر اليد على الحائط. ادفع للخارج كأنك ترفع الذراع للجانب. ثبّت الدفع لمدة 5–10 ثوانٍ دون حركة. استرخِ وكرر.', 1, 0, 'https://youtu.be/iaR5SZ0zHSM', now(), now(), false),
  (gen_random_uuid(), 'Forearm Supination', 3, 10, 10, 'Sit with the elbow bent at 90 degrees at your side. Hold a light weight in your hand, palm facing down. Slowly rotate the forearm so the palm faces upward. Keep the elbow tucked close to the body. Return slowly to start and repeat.', 'اجلس مع ثني الكوع 90 درجة بجانب الجسم. أمسك وزناً خفيفاً باليد وراحة اليد للأسفل. أدر الساعد ببطء حتى تصبح راحة اليد للأعلى. حافظ على تثبيت الكوع بجانب الجسم. عد ببطء للبداية وكرر.', 0, 1, 'https://youtu.be/41DzuAAjMl8', now(), now(), false),
  (gen_random_uuid(), 'Finkelstein Stretch', 3, 10, 10, 'Extend the affected arm in front with palm facing up. Bend the thumb into the palm. Wrap the fingers over the thumb to make a fist. Slowly bend the wrist downward and toward the pinky. Hold 15–20 seconds, feeling a stretch at the thumb side.', 'مدّ الذراع المصابة للأمام وراحة اليد للأعلى. اثنِ الإبهام داخل راحة اليد. لفّ الأصابع فوق الإبهام لتكوين قبضة. اثنِ الرسغ ببطء للأسفل ونحو الخنصر. ثبّت 15–20 ثانية مع الشعور بالشد في جهة الإبهام.', 0, 2, 'https://youtu.be/Wx9qgRKX7VY', now(), now(), false),
  (gen_random_uuid(), 'Frog Position Stretch', 3, 10, 10, 'Kneel on all fours on a soft surface. Slowly widen the knees out to the sides. Keep the ankles in line with the knees. Lower the hips back toward the heels. Hold 20–30 seconds while breathing calmly.', 'اركع على اليدين والركبتين على سطح ناعم. افتح الركبتين ببطء إلى الجانبين. حافظ على محاذاة الكاحلين مع الركبتين. أنزل الوركين للخلف نحو الكعبين. ثبّت 20–30 ثانية مع التنفس الهادئ.', 0, 5, 'https://youtu.be/NYbpk4LIJbM', now(), now(), false),
  (gen_random_uuid(), 'Frog Stretch', 3, 10, 10, 'Start on all fours on a soft mat. Bring the knees wide apart with feet pointing outward. Lower the forearms to the floor for support. Push the hips gently backward for a deeper stretch. Hold 20–30 seconds then release.', 'ابدأ على اليدين والركبتين على سجادة ناعمة. افرد الركبتين للجانبين والقدمان للخارج. أنزل الساعدين على الأرض للدعم. ادفع الوركين للخلف بلطف لتعميق الشد. ثبّت 20–30 ثانية ثم استرخِ.', 0, 5, 'https://youtu.be/H1sktS1SNGI', now(), now(), false),
  (gen_random_uuid(), 'Hip Flexors Stretch', 3, 10, 10, 'Kneel on one knee with the other foot flat in front. Keep the back straight and core engaged. Shift your hips forward gently. Feel the stretch across the front of the back thigh. Hold 20–30 seconds then switch sides.', 'اركع على ركبة واحدة والقدم الأخرى مسطحة أمامك. حافظ على استقامة الظهر وشد عضلات البطن. ادفع الوركين للأمام بلطف. اشعر بالشد في مقدمة الفخذ الخلفي. ثبّت 20–30 ثانية ثم بدّل.', 0, 5, 'https://youtu.be/C7A1P58EQUQ', now(), now(), false),
  (gen_random_uuid(), 'Isolated DIP Joint Flexion', 3, 10, 10, 'Rest your hand flat on a table, palm up. Stabilize the middle joint of the finger with your other hand. Slowly bend only the fingertip joint downward. Hold at the bent position briefly. Straighten slowly and repeat with each finger.', 'ضع يدك مسطحة على طاولة وراحة اليد للأعلى. ثبّت المفصل الأوسط للإصبع باليد الأخرى. اثنِ فقط مفصل رأس الإصبع للأسفل ببطء. ثبّت في وضع الثني لحظة. افرد ببطء وكرر مع كل إصبع.', 0, 2, 'https://youtu.be/BQ-ImPlw9xw', now(), now(), false),
  (gen_random_uuid(), 'Isolated MCP Joint Flexion', 3, 10, 10, 'Rest the forearm on a table with the palm up. Keep the finger joints straight except the knuckle. Slowly bend the finger at the knuckle joint only. Hold at the bent position briefly. Straighten and repeat with each finger.', 'ضع الساعد على طاولة وراحة اليد للأعلى. حافظ على استقامة مفاصل الإصبع ما عدا المفصل الأساسي. اثنِ الإصبع فقط من المفصل الأساسي ببطء. ثبّت في وضع الثني لحظة. افرد وكرر مع كل إصبع.', 0, 2, 'https://youtu.be/tIpH45o6MhM', now(), now(), false),
  (gen_random_uuid(), 'Isolated Thumb Flexion', 3, 10, 10, 'Rest the hand flat on a table, palm up. Keep the fingers relaxed and still. Slowly bend the thumb toward the palm. Hold the bent position for 3–5 seconds. Return the thumb to start and repeat.', 'ضع اليد مسطحة على طاولة وراحة اليد للأعلى. حافظ على استرخاء الأصابع وثباتها. اثنِ الإبهام ببطء نحو راحة اليد. ثبّت وضع الثني لمدة 3–5 ثوانٍ. عد بالإبهام للبداية وكرر.', 0, 2, 'https://youtu.be/BZRtUUH62lI', now(), now(), false),
  (gen_random_uuid(), 'Isometric External Rotation', 3, 10, 10, 'Stand next to a wall with the elbow bent 90 degrees at your side. Place the back of your hand against the wall. Push outward into the wall as if rotating the arm out. Hold the push for 5–10 seconds without moving. Relax and repeat.', 'قف بجانب حائط والكوع مثني 90 درجة بجانب الجسم. ضع ظهر اليد على الحائط. ادفع للخارج ضد الحائط كأنك تدير الذراع للخارج. ثبّت الدفع لمدة 5–10 ثوانٍ دون حركة. استرخِ وكرر.', 1, 0, 'https://youtu.be/wU724LrckAo', now(), now(), false),
  (gen_random_uuid(), 'Isometric Internal Rotation', 3, 10, 10, 'Stand next to a wall with the elbow bent 90 degrees. Place the palm of the hand against the wall. Push into the wall as if rotating the arm inward. Hold the push for 5–10 seconds without moving. Relax and repeat.', 'قف بجانب حائط والكوع مثني 90 درجة. ضع راحة اليد على الحائط. ادفع الحائط كأنك تدير الذراع للداخل. ثبّت الدفع لمدة 5–10 ثوانٍ دون حركة. استرخِ وكرر.', 1, 0, 'https://youtu.be/gUcgfeCkWsE', now(), now(), false),
  (gen_random_uuid(), 'Isometric Shoulder Extension', 3, 10, 10, 'Stand with your back against a wall. Keep the arm straight at your side. Press the back of the hand backward into the wall. Hold the push for 5–10 seconds without moving. Relax and repeat.', 'قف وظهرك ملاصق للحائط. حافظ على استقامة الذراع بجانب الجسم. اضغط ظهر اليد للخلف على الحائط. ثبّت الدفع لمدة 5–10 ثوانٍ دون حركة. استرخِ وكرر.', 1, 0, 'https://youtu.be/HF_dS0fvFwI', now(), now(), false),
  (gen_random_uuid(), 'Isometric Shoulder Flexion', 3, 10, 10, 'Stand facing a wall at arm''s length. Keep the arm straight and place the palm on the wall. Push the hand forward into the wall. Hold the push for 5–10 seconds without moving. Relax and repeat.', 'قف مواجهاً للحائط على مسافة ذراع. حافظ على استقامة الذراع وضع راحة اليد على الحائط. ادفع اليد للأمام على الحائط. ثبّت الدفع لمدة 5–10 ثوانٍ دون حركة. استرخِ وكرر.', 1, 0, 'https://youtu.be/OhOIL7aOjbw', now(), now(), false),
  (gen_random_uuid(), 'Isometric Wrist Extension', 3, 10, 10, 'Rest the forearm on a table with the palm down. Place the other hand on top of the affected hand. Try to lift the hand upward while the other hand resists. Hold the push for 5–10 seconds without movement. Relax and repeat.', 'ضع الساعد على طاولة وراحة اليد للأسفل. ضع اليد الأخرى فوق اليد المصابة. حاول رفع اليد للأعلى مع مقاومة اليد الأخرى. ثبّت الدفع لمدة 5–10 ثوانٍ دون حركة. استرخِ وكرر.', 0, 2, 'https://youtu.be/dyyCgEqVK9s', now(), now(), false),
  (gen_random_uuid(), 'Knee-Supported Hamstring Stretch', 3, 10, 10, 'Sit on the floor with one leg straight in front. Bend the other knee with the foot against the inner thigh. Slowly hinge forward from the hips. Reach the hands toward the straight foot. Hold 20–30 seconds then switch sides.', 'اجلس على الأرض مع فرد ساق واحدة أمامك. اثنِ الركبة الأخرى والقدم على الفخذ الداخلي. انحنِ للأمام ببطء من الوركين. مدّ اليدين نحو القدم المستقيمة. ثبّت 20–30 ثانية ثم بدّل.', 0, 5, 'https://youtu.be/-cPJsiCXuT8', now(), now(), false),
  (gen_random_uuid(), 'McKenzie Stretch', 3, 10, 10, 'Lie face down on the floor. Place your hands under your shoulders like a push-up. Slowly press up, lifting the chest and upper back. Keep the hips flat on the floor. Hold 3–5 seconds then lower and repeat.', 'استلقِ على البطن على الأرض. ضع اليدين تحت الكتفين كتمرين الضغط. ادفع للأعلى ببطء لرفع الصدر وأعلى الظهر. حافظ على تثبيت الوركين على الأرض. ثبّت 3–5 ثوانٍ ثم أنزل وكرر.', 0, 3, 'https://youtu.be/dqLvJEcb9PE', now(), now(), false),
  (gen_random_uuid(), 'Kneeling Back Extensions', 3, 10, 10, 'Kneel with hands under shoulders and knees under hips. Keep a neutral spine as your starting position. Slowly arch the back by lifting the chest and looking up. Feel a stretch along the front of the body. Return to neutral and repeat gently.', 'اركع مع اليدين تحت الكتفين والركبتين تحت الوركين. حافظ على وضع محايد للعمود الفقري كبداية. قوّس الظهر ببطء برفع الصدر والنظر للأعلى. اشعر بالشد على مقدمة الجسم. عد للوضع المحايد وكرر بلطف.', 0, 3, 'https://youtu.be/ptnXkfoIS_c', now(), now(), false),
  (gen_random_uuid(), 'Kneeling Lats Stretch', 3, 10, 10, 'Kneel in front of a chair or bench. Place both forearms on the surface, palms up. Sit the hips back toward the heels. Let the chest drop toward the floor. Hold 20–30 seconds then release.', 'اركع أمام كرسي أو مقعد. ضع الساعدين على السطح وراحة اليدين للأعلى. ادفع الوركين للخلف نحو الكعبين. اترك الصدر ينزل نحو الأرض. ثبّت 20–30 ثانية ثم استرخِ.', 0, 0, 'https://youtu.be/8aOrzh_zumg', now(), now(), false),
  (gen_random_uuid(), 'Lateral Raises', 3, 10, 10, 'Stand tall with a light dumbbell in each hand. Keep the arms straight at your sides. Raise both arms out to the sides to shoulder height. Pause briefly at the top position. Lower the weights slowly and repeat.', 'قف بشكل مستقيم ودمبل خفيف بكل يد. حافظ على استقامة الذراعين بجانب الجسم. ارفع الذراعين للجانبين حتى مستوى الكتف. توقف لحظة في وضع الأعلى. أنزل الأوزان ببطء وكرر.', 1, 0, 'https://youtu.be/I0QHglyATUk', now(), now(), false),
  (gen_random_uuid(), 'Lats Prayer Stretch', 3, 10, 10, 'Kneel on the floor and sit back on your heels. Place both palms together in front of you. Reach the arms forward along the floor. Press the chest and armpits toward the ground. Hold 20–30 seconds while breathing slowly.', 'اركع على الأرض واجلس على كعبيك. ضع راحتي اليدين معاً أمامك. مدّ الذراعين للأمام على الأرض. اضغط الصدر والإبطين نحو الأرض. ثبّت 20–30 ثانية مع التنفس البطيء.', 0, 0, 'https://youtu.be/RHyn1mIG_dE', now(), now(), false),
  (gen_random_uuid(), 'Legs Split with Trunk Flexion', 3, 10, 10, 'Sit on the floor with legs spread wide apart. Keep the knees pointing upward and toes flexed. Slowly hinge forward from the hips. Walk the hands forward as far as comfortable. Hold 20–30 seconds then return upright.', 'اجلس على الأرض مع فتح الساقين للجانبين. حافظ على توجيه الركبتين للأعلى وثني أصابع القدم. انحنِ للأمام ببطء من الوركين. مدّ اليدين للأمام قدر ما تسمح الراحة. ثبّت 20–30 ثانية ثم عد للجلوس.', 0, 5, 'https://youtu.be/N-MRiakK2ec', now(), now(), false),
  (gen_random_uuid(), 'Levator Scapula Stretch', 3, 10, 10, 'Sit tall and look down toward the opposite armpit. Place the same-side hand on top of your head. Gently pull the head diagonally forward and down. Feel the stretch along the back of the neck. Hold 20–30 seconds then switch sides.', 'اجلس بشكل مستقيم وانظر للأسفل نحو الإبط المعاكس. ضع يد نفس الجهة فوق الرأس. اسحب الرأس بلطف قطرياً للأمام وللأسفل. اشعر بالشد على خلفية الرقبة. ثبّت 20–30 ثانية ثم بدّل.', 0, 3, 'https://youtu.be/KKS9JfFwMnU', now(), now(), false),
  (gen_random_uuid(), 'Long Sitting Heel Slides', 3, 10, 10, 'Sit on the floor with legs straight in front. Keep the back tall and hands beside your hips. Slowly slide one heel toward the buttock, bending the knee. Then slide the heel back out to straight. Repeat with the same leg, then switch.', 'اجلس على الأرض مع فرد الساقين أمامك. حافظ على استقامة الظهر واليدان بجانب الوركين. اسحب كعب واحد ببطء نحو الأرداف مع ثني الركبة. ثم اسحب الكعب للخلف حتى تستقيم الساق. كرر بنفس الساق ثم بدّل.', 0, 6, 'https://youtu.be/6eeuSBnmkXk', now(), now(), false),
  (gen_random_uuid(), 'Lumbar Rotation', 3, 10, 10, 'Lie on your back with knees bent, feet flat on the floor. Keep the shoulders pressed to the ground. Slowly drop both knees to one side. Feel a gentle rotation in the lower back. Return to center and drop to the other side.', 'استلقِ على ظهرك مع ثني الركبتين والقدمين على الأرض. حافظ على تثبيت الكتفين على الأرض. أنزل الركبتين ببطء إلى جانب واحد. اشعر بلف لطيف في أسفل الظهر. عد للوسط وأنزل للجانب الآخر.', 0, 3, 'https://youtu.be/BWtOQn-gfNE', now(), now(), false),
  (gen_random_uuid(), 'Median Nerve Glide (2)', 3, 10, 10, 'Stand with the affected arm out to the side at shoulder height. Extend the wrist so the fingers point down. Tilt the head away from the arm. Then tilt the head toward the arm to release tension. Repeat the head tilts slowly and rhythmically.', 'قف مع فرد الذراع المصابة للجانب على مستوى الكتف. مدّ الرسغ حتى تشير الأصابع للأسفل. أمل الرأس بعيداً عن الذراع. ثم أمل الرأس نحو الذراع لتحرير التوتر. كرر إمالات الرأس ببطء وإيقاع.', 0, 2, 'https://youtu.be/K0o_iLQW-hU', now(), now(), false),
  (gen_random_uuid(), 'Median Nerve Glide', 3, 10, 10, 'Stand with the arm at your side, elbow bent. Extend the elbow while flipping the palm upward. At the same time, extend the wrist and fingers backward. Tilt the head to the opposite side. Return to start and repeat smoothly.', 'قف والذراع بجانب الجسم والكوع مثني. افرد الكوع مع قلب راحة اليد للأعلى. في نفس الوقت، مدّ الرسغ والأصابع للخلف. أمل الرأس للجهة المعاكسة. عد للبداية وكرر بسلاسة.', 0, 2, 'https://youtu.be/A9WIb7byFkY', now(), now(), false),
  (gen_random_uuid(), 'Metacarpals Flexion', 3, 10, 10, 'Rest the forearm on a table with the palm up. Keep the finger joints straight. Bend only the knuckles, folding the fingers as one unit. Hold at the bent position briefly. Straighten slowly and repeat.', 'ضع الساعد على طاولة وراحة اليد للأعلى. حافظ على استقامة مفاصل الأصابع. اثنِ المفاصل الأساسية فقط لطي الأصابع كوحدة. ثبّت وضع الثني لحظة. افرد ببطء وكرر التمرين.', 0, 2, 'https://youtu.be/0FFFKPGdnzQ', now(), now(), false),
  (gen_random_uuid(), 'Neck Frontal Ball Stability', 3, 10, 10, 'Place a soft ball between your forehead and a wall. Stand with feet slightly apart for balance. Press the forehead gently into the ball. Hold the press for 5–10 seconds. Relax and repeat.', 'ضع كرة طرية بين جبهتك والحائط. قف والقدمان متباعدتان قليلاً للتوازن. اضغط الجبهة بلطف على الكرة. ثبّت الضغطة لمدة 5–10 ثوانٍ. استرخِ وكرر.', 0, 3, 'https://youtu.be/2mDmdUfFdpM', now(), now(), false),
  (gen_random_uuid(), 'Neck Full Rotation', 3, 10, 10, 'Sit or stand tall with shoulders relaxed. Slowly turn the head to one side as far as comfortable. Hold at the end range for 2–3 seconds. Return to center then turn to the other side. Repeat several rotations each way.', 'اجلس أو قف بشكل مستقيم مع استرخاء الكتفين. أدر الرأس ببطء إلى جهة واحدة قدر ما تسمح الراحة. ثبّت في نهاية الحركة لمدة 2–3 ثوانٍ. عد للوسط ثم أدر للجهة الأخرى. كرر عدة دورات لكل جهة.', 0, 3, 'https://youtu.be/1nfulyJVQoA', now(), now(), false),
  (gen_random_uuid(), 'Neck Occipital Ball Stability', 3, 10, 10, 'Place a soft ball between the back of your head and a wall. Stand with feet slightly apart for balance. Press the back of the head gently into the ball. Hold the press for 5–10 seconds. Relax and repeat.', 'ضع كرة طرية بين مؤخرة الرأس والحائط. قف والقدمان متباعدتان قليلاً للتوازن. اضغط مؤخرة الرأس بلطف على الكرة. ثبّت الضغطة لمدة 5–10 ثوانٍ. استرخِ وكرر.', 0, 3, 'https://youtu.be/T1IEO7sDbkU', now(), now(), false),
  (gen_random_uuid(), 'Neck Retraction', 3, 10, 10, 'Sit or stand tall with shoulders relaxed. Look straight ahead with the chin level. Slowly draw the chin straight back, making a "double chin." Hold the retracted position for 3–5 seconds. Relax and repeat.', 'اجلس أو قف بشكل مستقيم مع استرخاء الكتفين. انظر للأمام مباشرة والذقن بمستوى أفقي. اسحب الذقن للخلف ببطء لتكوين "ذقن مزدوج". ثبّت الوضع المسحوب لمدة 3–5 ثوانٍ. استرخِ وكرر.', 0, 3, 'https://youtu.be/z0Z8xJ13FPM', now(), now(), false),
  (gen_random_uuid(), 'Neck Rotation', 3, 10, 10, 'Sit or stand tall with shoulders relaxed. Keep the chin level throughout the movement. Slowly turn the head to one side as far as comfortable. Return to center and turn to the opposite side. Repeat several rotations to each side.', 'اجلس أو قف بشكل مستقيم مع استرخاء الكتفين. حافظ على مستوى الذقن طوال الحركة. أدر الرأس ببطء إلى جهة قدر ما تسمح الراحة. عد للوسط ثم أدر إلى الجهة الأخرى. كرر عدة دورات لكل جهة.', 0, 3, 'https://youtu.be/jv6d2td8PSY', now(), now(), false),
  (gen_random_uuid(), 'Neck Side Ball Stability', 3, 10, 10, 'Place a soft ball between the side of your head and a wall. Stand with feet slightly apart for balance. Press the head gently sideways into the ball. Hold the press for 5–10 seconds without moving. Relax and repeat on both sides.', 'ضع كرة طرية بين جانب الرأس والحائط. قف والقدمان متباعدتان قليلاً للتوازن. اضغط الرأس بلطف جانبياً على الكرة. ثبّت الضغطة لمدة 5–10 ثوانٍ دون حركة. استرخِ وكرر على الجهتين.', 0, 3, 'https://youtu.be/4ulxZhqx9-4', now(), now(), false),
  (gen_random_uuid(), 'Neck Side-to-Side Bending', 3, 10, 10, 'Sit or stand tall with shoulders relaxed. Slowly tilt the ear toward the shoulder on one side. Keep the shoulder down and avoid lifting it. Hold at the end range for 2–3 seconds. Return to center and tilt to the other side.', 'اجلس أو قف بشكل مستقيم مع استرخاء الكتفين. أمل الأذن ببطء نحو الكتف من جهة واحدة. حافظ على إنزال الكتف وتجنب رفعه. ثبّت في نهاية الحركة لمدة 2–3 ثوانٍ. عد للوسط ثم أمل للجهة الأخرى.', 0, 3, 'https://youtu.be/w4NEqtdymbo', now(), now(), false),
  (gen_random_uuid(), 'Neck Traction', 3, 10, 10, 'Lie on your back with knees bent and head supported. Place both hands gently behind the base of your skull. Pull the head lightly upward, lengthening the neck. Hold the gentle pull for 10–15 seconds. Release slowly and repeat.', 'استلقِ على ظهرك مع ثني الركبتين ودعم الرأس. ضع كلتا اليدين بلطف خلف قاعدة الجمجمة. اسحب الرأس للأعلى بخفة لإطالة الرقبة. ثبّت السحب اللطيف لمدة 10–15 ثانية. استرخِ ببطء وكرر.', 0, 3, 'https://youtu.be/fTLn2B77XQM', now(), now(), false),
  (gen_random_uuid(), 'One-Side Squat', 3, 10, 10, 'Stand on one leg with the other lifted slightly in front. Keep the chest lifted and core engaged. Slowly bend the standing knee and lower the hips. Go down as far as safely controlled. Push through the heel to return upright.', 'قف على ساق واحدة والأخرى مرفوعة قليلاً للأمام. حافظ على رفع الصدر وشد عضلات البطن. اثنِ ركبة الوقوف ببطء وأنزل الوركين. انزل لأقصى مدى آمن ومتحكم به. ادفع من خلال الكعب للعودة للوقوف.', 2, 6, 'https://youtu.be/gP74tx5XCW4', now(), now(), false),
  (gen_random_uuid(), 'Overhead Stretch with Towel', 3, 10, 10, 'Stand or sit tall holding a towel with both hands. Raise the towel overhead with arms straight. Gently pull the towel apart to activate the shoulders. Reach as high as comfortable, lengthening the spine. Hold 15–20 seconds then lower slowly.', 'قف أو اجلس بشكل مستقيم ممسكاً بمنشفة بكلتا اليدين. ارفع المنشفة فوق الرأس والذراعان مستقيمتان. اسحب المنشفة بلطف للخارج لتفعيل الكتفين. امتد لأعلى ارتفاع مريح مع إطالة العمود الفقري. ثبّت لمدة 15–20 ثانية ثم أنزل ببطء.', 0, 0, 'https://youtu.be/3KkEVfiGVyE', now(), now(), false),
  (gen_random_uuid(), 'Overpressure Neck Side bend', 3, 10, 10, 'Sit tall and tilt the right ear toward the right shoulder. Place the right hand gently over the top of the head. Add light pressure to deepen the stretch. Keep the opposite shoulder relaxed and down. Hold 20–30 seconds then switch sides.', 'اجلس بشكل مستقيم وأمل الأذن اليمنى نحو الكتف الأيمن. ضع اليد اليمنى بلطف فوق الرأس. أضف ضغطاً خفيفاً لتعميق الشد. حافظ على استرخاء الكتف المعاكس وإنزاله. ثبّت لمدة 20–30 ثانية ثم بدّل.', 0, 3, 'https://youtu.be/GqDQkK3IH-4', now(), now(), false),
  (gen_random_uuid(), 'Overhead Elbow Extension', 3, 10, 10, 'Stand or sit tall holding a light dumbbell with both hands. Raise the weight straight overhead with elbows extended. Slowly bend the elbows, lowering the weight behind the head. Keep the upper arms still and pointed upward. Straighten the arms back up and repeat.', 'قف أو اجلس بشكل مستقيم ممسكاً بدمبل خفيف بكلتا اليدين. ارفع الوزن فوق الرأس مباشرة والذراعان مفرودتان. اثنِ الكوعين ببطء لإنزال الوزن خلف الرأس. حافظ على ثبات الذراعين العلويتين متجهتين للأعلى. افرد الذراعين للأعلى وكرر.', 1, 1, 'https://youtu.be/Ijf9WfxGZAc', now(), now(), false),
  (gen_random_uuid(), 'Prayer Stretch', 3, 10, 10, 'Stand or sit and place both palms together in front of the chest. Keep the elbows lifted and level with the wrists. Slowly lower the hands toward the waist while pressing palms. Feel a stretch through the wrists and forearms. Hold 15–20 seconds then release.', 'قف أو اجلس وضع راحتي اليدين معاً أمام الصدر. حافظ على رفع الكوعين بمستوى الرسغين. أنزل اليدين ببطء نحو الخصر مع ضغط الراحتين معاً. اشعر بالشد في الرسغين والساعدين. ثبّت لمدة 15–20 ثانية ثم استرخِ.', 0, 2, 'https://youtu.be/YfmXqgQ9rqo', now(), now(), false),
  (gen_random_uuid(), 'Pelvic Tilting', 3, 10, 10, 'Lie on your back with knees bent and feet flat on the floor. Place your hands at your sides for support. Flatten the lower back by tilting the pelvis upward. Hold the tilted position for 3–5 seconds. Relax and repeat.', 'استلقِ على ظهرك مع ثني الركبتين ووضع القدمين على الأرض. ضع اليدين على الجانبين للدعم. سطّح أسفل الظهر عن طريق إمالة الحوض للأعلى. ثبّت وضع الإمالة لمدة 3–5 ثوانٍ. استرخِ وكرر.', 0, 3, 'https://youtu.be/xEVf-IivCTo', now(), now(), false),
  (gen_random_uuid(), 'Piriformis Stretch', 3, 10, 10, 'Lie on your back with knees bent, feet flat on the floor. Cross one ankle over the opposite thigh. Grasp behind the bottom thigh with both hands. Pull the leg gently toward the chest. Hold 20–30 seconds then switch sides.', 'استلقِ على ظهرك مع ثني الركبتين والقدمين على الأرض. ضع كاحل قدم على الفخذ المعاكس. أمسك خلف الفخذ السفلي بكلتا اليدين. اسحب الساق بلطف نحو الصدر. ثبّت 20–30 ثانية ثم بدّل.', 0, 5, 'https://youtu.be/wQuOzM6f2JA', now(), now(), false),
  (gen_random_uuid(), 'Plank', 3, 10, 10, 'Lie face down and prop yourself on the forearms and toes. Keep the elbows directly under the shoulders. Lift the body into a straight line from head to heels. Engage the core and squeeze the glutes. Hold as long as possible with good form.', 'استلقِ على البطن واستند على الساعدين وأصابع القدمين. حافظ على الكوعين تحت الكتفين مباشرة. ارفع الجسم في خط مستقيم من الرأس إلى الكعبين. شدّ عضلات البطن واضغط عضلات الأرداف. ثبّت لأطول فترة ممكنة مع الحفاظ على الوضع.', 2, 4, 'https://youtu.be/7k8GfDqrehw', now(), now(), false),
  (gen_random_uuid(), 'Prone Elbow Flexion', 3, 10, 10, 'Lie face down on a bench with the arm hanging over the side. Hold a light dumbbell with the palm facing forward. Slowly bend the elbow, curling the weight toward the shoulder. Keep the upper arm still throughout the movement. Lower the weight with control and repeat.', 'استلقِ على البطن على مقعد والذراع متدلية من الجانب. أمسك دمبل خفيف وراحة اليد للأمام. اثنِ الكوع ببطء ولفّ الوزن نحو الكتف. حافظ على ثبات الذراع العلوية طوال الحركة. أنزل الوزن بتحكم وكرر.', 1, 1, 'https://youtu.be/MSzPpoysrcI', now(), now(), false);
